import {achievements,validateState,safeUrl,progress} from './model.js';
import {readJournal,writeJournal} from './storage.js';
const storage={getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)};
const loaded=readJournal(storage);let state=loaded.state,pending=null,storageBlocked=loaded.blocked;
const notice=document.querySelector('#notice');
function announce(message,error=false){notice.textContent=message;notice.classList.toggle('error',error);}
if(storageBlocked)announce('Сохранённый журнал недоступен или повреждён. Автосохранение остановлено, чтобы не перезаписать его. Для восстановления импортируй резервную копию.',true);
function save(){const persisted=!storageBlocked&&writeJournal(storage,state);announce(persisted?'Сохранено на этом устройстве.':storageBlocked?'Автосохранение остановлено. Исходный журнал не изменён. Экспортируй текущие отметки или импортируй резервную копию.':'Браузер не смог сохранить изменения. Экспортируй JSON, чтобы не потерять их.',!persisted);updateSummary();return persisted;}
function updateSummary(){const count=Object.values(state.entries).filter(e=>e.confirmed).length;document.querySelector('#total').textContent=`${count} / 6`;document.querySelector('#total-bar').style.width=`${count/6*100}%`;}
const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node;};
function render(){const cards=document.querySelector('#cards');cards.replaceChildren();for(const a of achievements){const entry=state.entries[a.id];const card=el('article',undefined,'card');const top=el('div',undefined,'card-top');top.append(el('span',a.icon,'badge '+a.color),el('span',entry.confirmed?'Подтверждено':'В процессе','status '+(entry.confirmed?'done':'')));card.append(top,el('h3',a.name),el('p',a.description,'description'));
 const label=el('label',a.unit,'count-label');const input=el('input');input.type='number';input.min='0';input.max='100000000';input.step='1';input.value=entry.count;input.id='count-'+a.id;label.htmlFor=input.id;card.append(label,input);
 const meter=el('progress');meter.max=100;meter.setAttribute('aria-label','Прогресс '+a.name);const detail=el('p',undefined,'progress-label');const tiers=el('div',undefined,'tiers');
 function updateProgress(){const p=progress(a,entry.count);meter.value=p.percent;detail.textContent=p.remaining?`${entry.count} / ${p.target} · осталось ${p.remaining}`:'Все пороги выполнены';tiers.replaceChildren(...a.tiers.map((n,i)=>el('span',`${['База','×2','×3','×4'][i]} · ${n}`,entry.count>=n?'reached':'')));}updateProgress();
 input.addEventListener('change',()=>{const n=input.valueAsNumber;if(!Number.isSafeInteger(n)||n<0||n>100000000){input.value=entry.count;announce('Введи целое число от 0 до 100 000 000.',true);return;}entry.count=n;updateProgress();save();});card.append(meter,detail,tiers);
 const checkLabel=el('label',undefined,'confirmation');const check=el('input');check.type='checkbox';check.setAttribute('aria-label',a.name+': значок появился в профиле');check.checked=entry.confirmed;check.addEventListener('change',()=>{entry.confirmed=check.checked;top.lastChild.textContent=check.checked?'Подтверждено':'В процессе';top.lastChild.classList.toggle('done',check.checked);save();});checkLabel.append(check,document.createTextNode('Значок появился в профиле'));card.append(checkLabel);
 const details=el('details');details.setAttribute('aria-label','Подтверждения '+a.name);details.append(el('summary',`Подтверждения (${entry.evidence.length})`),el('p',a.hint,'hint'));const links=el('ul');
 function drawLinks(){links.replaceChildren();entry.evidence.forEach((url,index)=>{const li=el('li');const link=el('a',new URL(url).pathname);link.href=url;link.target='_blank';link.rel='noopener noreferrer';const remove=el('button','×','remove');remove.type='button';remove.setAttribute('aria-label','Удалить ссылку '+new URL(url).pathname);remove.addEventListener('click',()=>{entry.evidence.splice(index,1);drawLinks();save();});li.append(link,remove);links.append(li);});details.querySelector('summary').textContent=`Подтверждения (${entry.evidence.length})`;}drawLinks();
 const form=el('form',undefined,'evidence-form');const urlInput=el('input');urlInput.type='url';urlInput.required=true;urlInput.placeholder='https://github.com/…';urlInput.setAttribute('aria-label','Ссылка для '+a.name);const add=el('button','Добавить');add.type='submit';form.append(urlInput,add);form.addEventListener('submit',event=>{event.preventDefault();try{const url=safeUrl(urlInput.value);if(entry.evidence.includes(url))throw new Error('Эта ссылка уже добавлена.');if(entry.evidence.length>=100)throw new Error('Не больше 100 ссылок на достижение.');if(url.length>2048)throw new Error('Ссылка слишком длинная.');entry.evidence.push(url);urlInput.value='';drawLinks();save();}catch(error){announce(error.message,true);}});details.append(links,form);card.append(details);cards.append(card);}updateSummary();}
render();
document.querySelector('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=el('a');link.href=url;link.download='achievement-journal.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Экспорт подготовлен. Сохрани файл как резервную копию.');});
const file=document.querySelector('#file'),dialog=document.querySelector('#import-dialog');document.querySelector('#import').addEventListener('click',()=>file.click());file.addEventListener('change',async()=>{try{const selected=file.files[0];if(!selected)return;if(selected.size>1024*1024)throw new Error('Файл больше 1 МБ. Выбери экспорт журнала.');pending=validateState(JSON.parse(await selected.text()));dialog.showModal();document.querySelector('#cancel-import').focus();}catch(error){pending=null;announce(error instanceof SyntaxError?'Не удалось прочитать JSON. Выбери корректный файл экспорта.':error.message,true);}finally{file.value='';}});
document.querySelector('#cancel-import').addEventListener('click',()=>{pending=null;dialog.close();});dialog.addEventListener('cancel',()=>{pending=null;});document.querySelector('#confirm-import').addEventListener('click',()=>{if(!pending)return;state=pending;pending=null;storageBlocked=false;render();const persisted=save();dialog.close();if(persisted)announce('Журнал импортирован и сохранён.');});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_achievement_journal',description:'Read locally recorded counts, confirmed badges and evidence. This is manual data, not verified GitHub activity.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>structuredClone(state)},{name:'update_achievement_count',description:'Save a manual achievement count on this device. Does not unlock a GitHub badge.',inputSchema:{type:'object',properties:{id:{type:'string',enum:achievements.map(a=>a.id)},count:{type:'integer',minimum:0,maximum:100000000}},required:['id','count'],additionalProperties:false},execute:({id,count})=>{if(!achievements.some(a=>a.id===id)||!Number.isSafeInteger(count)||count<0||count>100000000)throw new Error('Invalid achievement or count');state.entries[id].count=count;render();save();return {id,...state.entries[id]};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
